<script setup lang="ts">
import { onLaunch, onShow, onHide } from '@dcloudio/uni-app'
import { useAppStore } from '@/store'

onLaunch(() => {
  uni.__f__('log','at App.vue:6','App Launch')
})

onShow(() => {
  uni.__f__('log','at App.vue:10','App Show')
  // 应用显示时从云端拉取最新数据
  autoSyncFromWebDAV()
})

onHide(() => {
  uni.__f__('log','at App.vue:16','App Hide')
  // 应用隐藏时自动同步到 WebDAV
  autoSyncToWebDAV()
})

// 自动同步到 WebDAV（上传）
const autoSyncToWebDAV = async () => {
  const store = useAppStore()
  await store.syncToWebDAV()
}

// 自动从 WebDAV 同步（下载）
const autoSyncFromWebDAV = async () => {
  const store = useAppStore()
  const success = await store.syncFromWebDAV()
  if (success) {
    uni.__f__('log','at App.vue:32','从云端同步数据成功')
  }
}
</script>

